import { useRef, useState } from 'react'
import { Camera, Save, User } from 'lucide-react'
import { AppLayout } from '@/components/layout'
import Button from '@/components/ui/Button'
import Input from '@/components/ui/Input'
import { supabase } from '@/lib/supabase'
import { uploadAvatar } from '@/services/users'
import { toast } from '@/lib/toast'
import { useAuthContext } from '@/hooks/AuthProvider'
import '../Settings.css'

export default function ProfileScreen() {
  const { user } = useAuthContext()
  const [name, setName] = useState(user?.name || '')
  const [email] = useState(user?.email || '')
  const [avatarUrl, setAvatarUrl] = useState(user?.avatar_url || '')
  const [bio, setBio] = useState(user?.bio || '')
  const [slug, setSlug] = useState(user?.slug || '')
  const [currentPassword, setCurrentPassword] = useState('')
  const [newPassword, setNewPassword] = useState('')
  const [confirmPassword, setConfirmPassword] = useState('')
  const [saving, setSaving] = useState(false)
  const [savingPassword, setSavingPassword] = useState(false)
  const [uploading, setUploading] = useState(false)
  const fileInputRef = useRef<HTMLInputElement>(null)

  const handlePickFile = () => fileInputRef.current?.click()

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0]
    if (!file || !user) return

    if (!file.type.startsWith('image/')) {
      toast('Selecione um arquivo de imagem', 'error')
      return
    }
    if (file.size > 5 * 1024 * 1024) {
      toast('A imagem deve ter no máximo 5 MB', 'error')
      return
    }

    setUploading(true)
    try {
      const url = await uploadAvatar(user.id, file)
      setAvatarUrl(url)
      // Persiste imediatamente o avatar (não espera o "Salvar" do perfil)
      const { error } = await supabase.from('users').update({ avatar_url: url }).eq('id', user.id)
      if (error) throw error
      toast('Foto atualizada!')
    } catch {
      toast('Erro ao enviar a foto', 'error')
    } finally {
      setUploading(false)
      if (fileInputRef.current) fileInputRef.current.value = ''
    }
  }

  // Normaliza o slug: minúsculo, sem acento, só letras/números/hífen
  const normalizeSlug = (value: string) =>
    value
      .toLowerCase()
      .normalize('NFD')
      .replace(/[\u0300-\u036f]/g, '')
      .replace(/[^a-z0-9]+/g, '-')
      .replace(/^-+|-+$/g, '')

  const handleSaveProfile = async () => {
    if (!user) return

    const cleanSlug = normalizeSlug(slug)
    if (!cleanSlug) {
      toast('O link precisa de pelo menos uma letra ou número', 'error')
      return
    }

    setSaving(true)
    try {
      const { error } = await supabase
        .from('users')
        .update({
          name,
          avatar_url: avatarUrl.trim() || null,
          bio: bio.trim() || null,
          slug: cleanSlug,
        })
        .eq('id', user.id)

      if (error) {
        // Conflito de slug único por tenant
        if (error.code === '23505') {
          toast('Esse link já está em uso por outro profissional', 'error')
        } else {
          throw error
        }
        return
      }
      setSlug(cleanSlug)
      toast('Perfil atualizado!')
    } catch {
      toast('Erro ao atualizar perfil', 'error')
    } finally {
      setSaving(false)
    }
  }

  const handleChangePassword = async () => {
    if (newPassword !== confirmPassword) {
      toast('As senhas não conferem', 'error')
      return
    }

    if (newPassword.length < 6) {
      toast('A senha deve ter pelo menos 6 caracteres', 'error')
      return
    }

    setSavingPassword(true)
    try {
      const { error } = await supabase.auth.updateUser({
        password: newPassword,
      })

      if (error) throw error

      setCurrentPassword('')
      setNewPassword('')
      setConfirmPassword('')
      toast('Senha alterada com sucesso!')
    } catch {
      toast('Erro ao alterar senha', 'error')
    } finally {
      setSavingPassword(false)
    }
  }

  return (
    <AppLayout title="Meu Perfil" subtitle="Suas informações e acesso">
      <div className="settings-page">
        <div className="settings-section">
          {/* Avatar */}
          <div className="settings-card">
            <h3>Foto de Perfil</h3>
            <p className="settings-description">Aparece na sua página pública de agendamento.</p>
            <div className="avatar-section">
              <div className="avatar-preview">
                {avatarUrl ? <img src={avatarUrl} alt="" /> : <User size={48} />}
              </div>
              <div className="avatar-actions">
                <input
                  ref={fileInputRef}
                  type="file"
                  accept="image/*"
                  onChange={handleFileChange}
                  style={{ display: 'none' }}
                />
                <Button variant="secondary" size="sm" onClick={handlePickFile} disabled={uploading}>
                  <Camera size={16} />
                  {uploading ? 'Enviando...' : 'Alterar foto'}
                </Button>
                <p className="avatar-hint">JPG ou PNG, até 5 MB.</p>
              </div>
            </div>
          </div>

          {/* Perfil público (bio + link) */}
          <div className="settings-card">
            <h3>Perfil Público</h3>
            <p className="settings-description">
              Como você aparece para os clientes na página de agendamento.
            </p>
            <div className="settings-form">
              <div className="form-group">
                <label className="form-label">Bio</label>
                <textarea
                  className="form-input"
                  rows={3}
                  value={bio}
                  onChange={e => setBio(e.target.value)}
                  placeholder="Uma breve descrição sobre você e seu trabalho"
                />
              </div>
              <Input
                label="Link de agendamento"
                value={slug}
                onChange={e => setSlug(e.target.value)}
                placeholder="seu-nome"
                hint={`Sua página: /book/<consultório>/${normalizeSlug(slug) || 'seu-nome'}`}
              />
            </div>
          </div>

          {/* Basic Info */}
          <div className="settings-card">
            <h3>Informações Básicas</h3>
            <div className="settings-form">
              <Input
                label="Nome completo"
                value={name}
                onChange={e => setName(e.target.value)}
                placeholder="Seu nome"
              />
              <Input label="E-mail" value={email} disabled placeholder="Seu e-mail" />
              <div className="settings-form-actions">
                <Button onClick={handleSaveProfile} disabled={saving}>
                  <Save size={18} />
                  {saving ? 'Salvando...' : 'Salvar alterações'}
                </Button>
              </div>
            </div>
          </div>

          {/* Change Password */}
          <div className="settings-card">
            <h3>Alterar Senha</h3>
            <div className="settings-form">
              <Input
                label="Senha atual"
                type="password"
                value={currentPassword}
                onChange={e => setCurrentPassword(e.target.value)}
                placeholder="••••••••"
              />
              <Input
                label="Nova senha"
                type="password"
                value={newPassword}
                onChange={e => setNewPassword(e.target.value)}
                placeholder="••••••••"
              />
              <Input
                label="Confirmar nova senha"
                type="password"
                value={confirmPassword}
                onChange={e => setConfirmPassword(e.target.value)}
                placeholder="••••••••"
              />
              <div className="settings-form-actions">
                <Button
                  variant="secondary"
                  onClick={handleChangePassword}
                  disabled={savingPassword || !newPassword}
                >
                  {savingPassword ? 'Alterando...' : 'Alterar senha'}
                </Button>
              </div>
            </div>
          </div>
        </div>
      </div>
    </AppLayout>
  )
}
